PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, salt TEXT NOT NULL, password TEXT NOT NULL, driver_id INTEGER);
CREATE TABLE IF NOT EXISTS patients(id INTEGER PRIMARY KEY, name TEXT NOT NULL, cpf TEXT UNIQUE, cns TEXT, birth TEXT, phone TEXT, address TEXT NOT NULL, boarding TEXT NOT NULL, accessible INTEGER NOT NULL DEFAULT 0, companion TEXT, companion_cpf TEXT, bank TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS facilities(id INTEGER PRIMARY KEY, name TEXT NOT NULL, cnes TEXT NOT NULL UNIQUE, city TEXT NOT NULL, address TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY, name TEXT NOT NULL, plate TEXT NOT NULL UNIQUE, capacity INTEGER NOT NULL CHECK(capacity>0), accessible INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS drivers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, license TEXT, valid_until TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL REFERENCES patients(id), facility_id INTEGER NOT NULL REFERENCES facilities(id), kind TEXT NOT NULL CHECK(kind IN ('TFD','Transporte sanitário')), specialty TEXT NOT NULL, companion INTEGER NOT NULL DEFAULT 0, start_date TEXT NOT NULL, end_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Em análise', reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trips(id INTEGER PRIMARY KEY, date TEXT NOT NULL, departure TEXT NOT NULL, arrival TEXT NOT NULL, destination TEXT NOT NULL, route TEXT NOT NULL, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id), driver_id INTEGER NOT NULL REFERENCES drivers(id), estimated_km REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Planejada', km REAL NOT NULL DEFAULT 0, liters REAL NOT NULL DEFAULT 0, cost_cents INTEGER NOT NULL DEFAULT 0, notes TEXT);
CREATE TABLE IF NOT EXISTS occurrences(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id), date TEXT NOT NULL, trip_id INTEGER REFERENCES trips(id), confirmation TEXT NOT NULL DEFAULT 'Pendente', boarding TEXT NOT NULL DEFAULT 'Pendente', attendance INTEGER NOT NULL DEFAULT 0, companion_proof INTEGER NOT NULL DEFAULT 0, permanence TEXT, UNIQUE(request_id,date));
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY, request_id INTEGER REFERENCES requests(id), occurrence_id INTEGER REFERENCES occurrences(id), kind TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, hash TEXT NOT NULL, content BLOB NOT NULL, created_at TEXT NOT NULL, user_id INTEGER REFERENCES users(id), CHECK((request_id IS NOT NULL) != (occurrence_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS rules(id INTEGER PRIMARY KEY, patient_cents INTEGER NOT NULL CHECK(patient_cents>=0), companion_cents INTEGER NOT NULL CHECK(companion_cents>=0), label TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS benefits(id INTEGER PRIMARY KEY, occurrence_id INTEGER NOT NULL REFERENCES occurrences(id), beneficiary TEXT NOT NULL CHECK(beneficiary IN ('Paciente','Acompanhante')), rule_id INTEGER NOT NULL REFERENCES rules(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), status TEXT NOT NULL DEFAULT 'Calculado', accounting_ref TEXT, payment_date TEXT, UNIQUE(occurrence_id,beneficiary));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, before_json TEXT, after_json TEXT, reason TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS occurrence_date ON occurrences(date);
CREATE INDEX IF NOT EXISTS audit_entity ON audit(entity,entity_id);
